import { expect, expectStatus, test } from "../../fixtures";

test.describe("vendor editing lock", () => {
  test(
    "a vendor under review cannot be edited",
    { tag: "@VEN-09" },
    async ({ apiAs }) => {
      // Arrange: a member creates a vendor and submits it, moving it to in_review.
      const member = await apiAs("member");
      const suffix = `${Date.now()}-${Math.random().toString(36).slice(2, 8)}`;

      const created = await expectStatus(
        await member.post("/api/vendors", {
          data: {
            name: `VEN-09 Vendor ${suffix}`,
            category: "services",
            contact_email: `ops+${suffix}@vendor.example`,
          },
        }),
        201,
      );

      const submitted = await expectStatus(
        await member.post(`/api/vendors/${created.id}/submit`),
        200,
      );
      expect(submitted.status).toBe("in_review");

      // Act: attempt to change the contact email while under review.
      const response = await member.patch(`/api/vendors/${created.id}`, {
        data: { contact_email: "billing@acmefreight.example" },
      });

      // Assert
      const body = await expectStatus<{ error: { code: string } }>(response, 409);
      expect(body.error.code).toBe("vendor_locked");
    },
  );
});
